WITH costs(cents) AS (VALUES(0),(10000),(50000),(150000)), targets(cents) AS (VALUES(25000),(50000),(100000),(200000),(400000)), deductions(bp) AS (VALUES(0),(1000),(2000)) SELECT lot_id,category,seller_asking_cents, costs.cents own_cost_scenario_cents,targets.cents target_contribution_cents, deductions.bp buyer_deduction_scenario_bp,CAST(ceil((seller_asking_cents+costs.cents+targets.cents)*10000.0/(10000-deductions.bp)) AS BIGINT) required_gross_bid_cents,'sensitivity_not_bid_or_forecast' basis FROM read_json_auto('/Users/nickgonzales/Developer/Bonfyre/packs/wholesale-20k/lots.snapshot.jsonl') CROSS JOIN costs CROSS JOIN targets CROSS JOIN deductions ORDER BY lot_id,own_cost_scenario_cents,target_contribution_cents,buyer_deduction_scenario_bp;
